const http = require('http');
const fs = require('fs');
const path = require('path');
const root = __dirname;
const port = 3002;
const mime = {'.html':'text/html','.js':'application/javascript','.css':'text/css','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg'};
http.createServer((req,res)=>{
  let p = req.url === '/' ? 'index.html' : req.url.split('?')[0].slice(1);
  p = path.normalize(p).replace(/^\.\.(\/|\\|$)/,'');
  const f = path.join(root,p);
  fs.readFile(f,(e,d)=>{ if(e){res.statusCode=404;res.end('Not found');return;} res.setHeader('Content-Type',mime[path.extname(f)]||'application/octet-stream');res.end(d); });
}).listen(port,'0.0.0.0',()=>console.log('Werewolf Survival http://localhost:'+port));

@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Roboto+Condensed:wght@400;700&display=swap');
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#09110f;font-family:'Roboto Condensed',sans-serif;color:#eee}
#game{position:relative;width:100vw;height:100vh;overflow:hidden;background:#101b17}canvas{display:block;width:100%;height:100%}
#hud{position:absolute;left:0;right:0;top:0;height:82px;padding:14px 38px 12px;display:grid;grid-template-columns:190px 1fr 190px;align-items:center;background:linear-gradient(180deg,rgba(5,10,8,.96),rgba(5,10,8,.72));border-bottom:1px solid rgba(220,204,164,.15);z-index:5}.brand{font-family:Oswald,sans-serif;line-height:.82}.brand b{display:block;font-size:27px;letter-spacing:3px;color:#efe4c6}.brand span{display:block;font-size:12px;letter-spacing:8px;color:#8c9b86;margin-top:8px}.level{text-align:center}.level>span{font-family:Oswald;font-size:12px;letter-spacing:3px;color:#b4c1a7}.bar{width:min(420px,70%);height:5px;background:#26332d;margin:8px auto 0}.bar i{display:block;height:100%;width:0%;background:#d4c793;box-shadow:0 0 10px #d4c793}.right{display:flex;justify-content:flex-end;gap:28px;text-align:right}.right div{display:flex;flex-direction:column}.right small{font-size:9px;letter-spacing:3px;color:#7e8d80}.right b{font-family:Oswald;font-size:20px;color:#eee;margin-top:3px}
#boss{position:absolute;bottom:20px;left:50%;transform:translateX(-50%);width:340px;text-align:center;opacity:0;transition:.3s}#boss.show{opacity:1}#boss span{font-family:Oswald;font-size:11px;letter-spacing:4px;color:#c8bba0}#boss div{height:5px;background:#201f1b;margin-top:7px;border:1px solid #665f50}#boss i{display:block;height:100%;width:100%;background:#a74e3d}
#cross{position:absolute;width:18px;height:18px;pointer-events:none;transform:translate(-50%,-50%);z-index:4}#cross span:first-child{position:absolute;left:8px;top:0;width:1px;height:18px;background:#d7cfb1}#cross span:last-child{position:absolute;top:8px;left:0;width:18px;height:1px;background:#d7cfb1}
.overlay{position:absolute;z-index:10;inset:0;display:flex;align-items:center;background:linear-gradient(90deg,rgba(5,10,8,.98) 0%,rgba(5,10,8,.82) 42%,rgba(5,10,8,.12) 100%);transition:.35s}.overlay.hidden{opacity:0;pointer-events:none}.panel{margin-left:9vw}.eyebrow{font-family:Oswald;font-size:12px;letter-spacing:5px;color:#aab89d;margin-bottom:18px}.panel h1{font-family:Oswald;font-size:clamp(72px,9vw,150px);line-height:.78;letter-spacing:-4px;margin:0;color:#ede6d2}.panel h1 em{font-style:normal;color:#b84331}.panel h2{font-family:Oswald;font-size:48px;margin:0 0 30px}.panel p{font-size:14px;letter-spacing:1px;color:#abb1a5;margin:28px 0}button{border:1px solid #a7a180;background:#b9af83;color:#101310;font-family:Oswald;font-weight:700;letter-spacing:3px;padding:16px 27px;cursor:pointer;transition:.18s}button:hover{background:#ece1b7;transform:translateY(-2px)}.keys{display:flex;gap:28px;margin-top:34px;font-size:9px;letter-spacing:2px;color:#879285}.keys kbd{border:1px solid #596158;padding:5px 7px;margin-right:7px;color:#ddd;font-family:Oswald}.moon{position:absolute;right:12%;top:12%;width:min(28vw,400px);height:min(28vw,400px);border-radius:50%;background:#cfd1be;box-shadow:0 0 80px rgba(208,211,187,.18);opacity:.8}.moon:after{content:"";position:absolute;width:70%;height:70%;border-radius:50%;left:-12%;top:-6%;background:rgba(5,10,8,.72);box-shadow:18px 4px 20px rgba(5,10,8,.5)}
.upgrade-panel{width:82vw;margin:0 auto;text-align:center}.upgrade-panel .eyebrow{margin-bottom:10px}.upgrade-panel h2{font-size:36px}#cards{display:flex;justify-content:center;gap:14px}.card{width:240px;height:280px;border:1px solid #556158;background:rgba(12,22,18,.95);padding:28px 20px;cursor:pointer;text-align:left;transition:.2s}.card:hover{border-color:#d1c69a;transform:translateY(-8px);background:#18251f}.card i{display:block;width:50px;height:50px;margin-bottom:35px;border:1px solid #7f8c7b;border-radius:50%;text-align:center;line-height:48px;font-style:normal;font-size:22px;color:#d4c793}.card small{display:block;font-family:Oswald;letter-spacing:3px;color:#94a18f}.card b{display:block;font-family:Oswald;font-size:24px;margin:8px 0}.card p{font-size:12px;line-height:1.5;margin:0}
@media(max-width:700px){#hud{padding:12px 14px;grid-template-columns:130px 1fr 125px}.brand b{font-size:20px}.brand span{letter-spacing:5px}.panel{margin-left:7vw}.moon{right:-10%;opacity:.35}.panel h1{font-size:68px}.card{width:30%;height:230px;padding:18px 12px}.card i{margin-bottom:20px}.card b{font-size:18px}.keys{display:none}}

const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
let W,H,dpr,started=false,paused=false,over=false,last=0,time=0,kills=0,xp=0,level=1,nextXP=20;
const mouse={x:0,y:0,down:false},keys={};
const player={x:0,y:0,r:19,hp:100,maxHp:100,speed:210,damage:24,rate:.38,range:270,proj:1,claws:0,fire:0};
let enemies=[],shots=[],gems=[],trees=[],particles=[];
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);if(!player.x){player.x=W/2;player.y=H/2}makeTrees()}addEventListener('resize',resize);resize();
function makeTrees(){trees=[];for(let i=0;i<110;i++)trees.push({x:Math.random()*W,y:Math.random()*H,s:20+Math.random()*38,a:Math.random()*6});}
addEventListener('keydown',e=>keys[e.key.toLower.toLowerCase?e.key.toLowerCase():e.key]=true);addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
addEventListener('mousemove',e=>{mouse.x=e.clientX;mouse.y=e.clientY;const c=document.getElementById('cross');c.style.left=e.clientX+'px';c.style.top=e.clientY+'px'});addEventListener('mousedown',()=>mouse.down=true);addEventListener('mouseup',()=>mouse.down=false);
function spawn(){const side=Math.floor(Math.random()*4),m=40;let x,y;if(side===0){x=Math.random()*W;y=-m}else if(side===1){x=W+m;y=Math.random()*H}else if(side===2){x=Math.random()*W;y=H+m}else{x=-m;y=Math.random()*H}
 const boss=time>10&&(Math.floor(time)%70===69&&time%70<time%1+.2)&&kills>20;const r=boss?38:11+Math.random()*7;
 enemies.push({x,y,r,hp:(boss?700:18+level*7)*(boss?1:1),maxHp:boss?700:18+level*7,boss,speed:(boss?46:38+Math.random()*38),hit:0,angle:Math.random()*6});}
let shotTimer=0;
function shoot(){if(shotTimer>0)return;shotTimer=player.rate;let a=Math.atan2(mouse.y-player.y,mouse.x-player.x);for(let i=0;i<player.proj;i++){let spread=(i-(player.proj-1)/2)*.13;shots.push({x:player.x,y:player.y,vx:Math.cos(a+spread)*520,vy:Math.sin(a+spread)*520,r:5,life:player.range/520})}}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function update(dt){time+=dt;document.getElementById('time').querySelector('b').textContent=String(Math.floor(time/60)).padStart(2,'0')+':'+String(Math.floor(time%60)).padStart(2,'0');
 let dx=(keys.d?1:0)-(keys.a?1:0),dy=(keys.s?1:0)-(keys.w?1:0);if(dx||dy){let n=Math.hypot(dx,dy);player.x+=dx/n*player.speed*dt;player.y+=dy/n*player.speed*dt}player.x=Math.max(25,Math.min(W-25,player.x));player.y=Math.max(100,Math.min(H-25,player.y));
 shotTimer-=dt;if(mouse.down)shoot();
 if(Math.random()<dt*(.35+time*.018))spawn();
 for(let s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt}shots=shots.filter(s=>s.life>0&&s.x>-20&&s.x<W+20&&s.y>-20&&s.y<H+20);
 for(let e of enemies){let a=Math.atan2(player.y-e.y,player.x-e.x);e.angle=a;e.x+=Math.cos(a)*e.speed*dt;e.y+=Math.sin(a)*e.speed*dt;e.hit-=dt;if(dist(e,player)<e.r+player.r){if(e.hit<=0){player.hp-=e.boss?16:9;e.hit=.7;particles.push({x:player.x,y:player.y,t:.25,c:'#aa4938'})} } }
 for(let s of shots)for(let e of enemies){if(s.life>0&&dist(s,e)<e.r+s.r){e.hp-=player.damage;s.life=0;e.hit=.12;for(let i=0;i<3;i++)particles.push({x:e.x,y:e.y,vx:(Math.random()-.5)*100,vy:(Math.random()-.5)*100,t:.35,c:'#d2c68e'})}}
 for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];if(e.hp<=0){kills++;xp+=e.boss?12:6;gems.push({x:e.x,y:e.y,r:5,v:0});if(e.boss){player.hp=Math.min(player.maxHp,player.hp+25);document.getElementById('boss').classList.remove('show')}enemies.splice(i,1)}}
 for(let g of gems){let d=Math.hypot(player.x-g.x,player.y-g.y);if(d<130){let a=Math.atan2(player.y-g.y,player.x-g.x);g.x+=Math.cos(a)*280*dt;g.y+=Math.sin(a)*280*dt}if(d<22){g.v=1}}gems=gems.filter(g=>g.v!==1);
 for(let p of particles){p.t-=dt;if(p.vx){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.95;p.vy*=.95}}particles=particles.filter(p=>p.t>0);
 if(xp>=nextXP){xp-=nextXP;level++;nextXP=Math.round(nextXP*1.42);showUpgrade()} 
 if(player.hp<=0)end(false);
 let boss=enemies.find(e=>e.boss);let bd=document.getElementById('boss');if(boss){bd.classList.add('show');bd.querySelector('i').style.width=(boss.hp/boss.maxHp*100)+'%'}else bd.classList.remove('show');
}
const upgrades=[['01','HUNGER','Razor Claws','More melee damage\nand faster attacks','claws'],['02','BLOOD','Blood Rite','Recover health\nwith every kill','blood'],['03','PACK','Triple Fang','Fire one more\nprojectile','proj'],['04','SWIFT','Lone Shadow','Move faster\nand dodge danger','speed'],['05','VOID','Black Arrow','Increase damage\nand attack range','damage']];
function showUpgrade(){paused=true;const cards=document.getElementById('cards');cards.innerHTML='';let pool=[...upgrades].sort(()=>Math.random()-.5).slice(0,3);pool.forEach(u=>{let el=document.createElement('div');el.className='card';el.innerHTML=`<i>${u[0]}</i><small>${u[1]}</small><b>${u[2]}</b><p>${u[3].replace('\n','<br>')}</p>`;el.onclick=()=>apply(u[4]);cards.appendChild(el)});document.getElementById('upgrade').classList.remove('hidden')}
function apply(kind){if(kind==='claws'){player.damage+=8;player.rate=Math.max(.18,player.rate-.05)}if(kind==='blood')player.maxHp+=18,player.hp=Math.min(player.maxHp,player.hp+25);if(kind==='proj')player.proj++;if(kind==='speed')player.speed+=35;if(kind==='damage'){player.damage+=12;player.range+=50}paused=false;document.getElementById('upgrade').classList.add('hidden')}
function end(win){over=true;paused=true;const end=document.getElementById('end');document.getElementById('endTag').textContent=win?'DAWN BREAKS':'THE NIGHT ENDS';document.getElementById('endTitle').innerHTML=win?'YOU OUTLIVED<br><em>THE NIGHT</em>':'YOU WERE<br><em>HUNTED</em>';document.getElementById('endStats').textContent=`${kills} kills  //  ${document.getElementById('time').querySelector('b').textContent} survived  //  level ${level}`;end.classList.remove('hidden')}
function draw(){ctx.clearRect(0,0,W,H);ctx.fillStyle='#111a16';ctx.fillRect(0,0,W,H);
 ctx.strokeStyle='rgba(154,170,146,.035)';ctx.lineWidth=1;for(let x=(player.x%50)-50;x<W;x+=50){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=(player.y%50)-50;y<H;y+=50){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
 for(let t of trees){let dx=t.x-player.x,dy=t.y-player.y;if(Math.abs(dx)<W/2+80&&Math.abs(dy)<H/2+80){ctx.save();ctx.translate(t.x,t.y);ctx.rotate(t.a);ctx.fillStyle='rgba(4,9,7,.55)';ctx.beginPath();ctx.ellipse(3,8,t.s*.28,t.s*.8,0,0,7);ctx.fill();ctx.fillStyle='#1c2a22';for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(0,-t.s*.3-i*5);ctx.lineTo(-t.s*.28+t.s*i*.025,-t.s*.05-i*5);ctx.lineTo(t.s*.28-t.s*i*.025,-t.s*.05-i*5);ctx.closePath();ctx.fill()}ctx.restore()}}
 ctx.fillStyle='#d1c99d';for(let g of gems){ctx.beginPath();ctx.moveTo(g.x,g.y-7);ctx.lineTo(g.x+5,g.y);ctx.lineTo(g.x,g.y+7);ctx.lineTo(g.x-5,g.y);ctx.closePath();ctx.fill()}
 for(let s of shots){ctx.fillStyle='#ddd39e';ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,7);ctx.fill();ctx.fillStyle='rgba(221,211,158,.18)';ctx.beginPath();ctx.arc(s.x,s.y,10,0,7);ctx.fill()}
 for(let e of enemies){ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.angle);ctx.fillStyle=e.boss?'#6d3329':(e.hit>0?'#a9a58d':'#526057');ctx.beginPath();if(e.boss){ctx.moveTo(-35,-25);ctx.lineTo(-22,-43);ctx.lineTo(-5,-30);ctx.lineTo(10,-45);ctx.lineTo(25,-27);ctx.lineTo(38,-17);ctx.lineTo(28,30);ctx.lineTo(-28,30);ctx.closePath()}else{ctx.moveTo(-e.r,-e.r*.6);ctx.lineTo(-e.r*.3,-e.r*1.15);ctx.lineTo(e.r*.2,-e.r*.7);ctx.lineTo(e.r*1.1,-e.r*.3);ctx.lineTo(e.r*.8,e.r*.8);ctx.lineTo(-e.r*.7,e.r);ctx.closePath()}ctx.fill();ctx.fillStyle='#bdb990';ctx.fillRect(e.r*.15,-5,4,3);ctx.restore();if(e.boss){ctx.fillStyle='#182018';ctx.fillRect(e.x-35,e.y-e.r-16,70,4);ctx.fillStyle='#a74e3d';ctx.fillRect(e.x-35,e.y-e.r-16,70*e.hp/e.maxHp,4)}}
 ctx.save();ctx.translate(player.x,player.y);let pa=Math.atan2(mouse.y-player.y,mouse.x-player.x);ctx.rotate(pa);ctx.fillStyle='#d6cfae';ctx.beginPath();ctx.moveTo(-18,-13);ctx.lineTo(-7,-18);ctx.lineTo(18,-8);ctx.lineTo(14,12);ctx.lineTo(-16,14);ctx.closePath();ctx.fill();ctx.fillStyle='#7f947d';ctx.beginPath();ctx.moveTo(-12,-10);ctx.lineTo(-28,-22);ctx.lineTo(-21,-5);ctx.closePath();ctx.fill();ctx.restore();
 ctx.fillStyle='rgba(0,0,0,.35)';ctx.fillRect(38,H-36,220,6);ctx.fillStyle='#a84c3a';ctx.fillRect(38,H-36,220*player.hp/player.maxHp,6);ctx.fillStyle='#9aa58f';ctx.font='11px Oswald';ctx.fillText('VITALITY',38,H-43);
 for(let p of particles){ctx.globalAlpha=Math.max(0,p.t*3);ctx.fillStyle=p.c;ctx.fillRect(p.x,p.y,4,4)}ctx.globalAlpha=1;
}
function loop(t){let dt=Math.min(.033,(t-last)/1000||0);last=t;if(started&&!paused&&!over)update(dt);draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);
function start(){started=true;over=false;paused=false;player.x=W/2;player.y=H/2;time=0;kills=0;xp=0;level=1;nextXP=20;player.hp=player.maxHp;enemies=[];shots=[];gems=[];document.getElementById('start').classList.add('hidden');document.getElementById('end').classList.add('hidden');document.getElementById('upgrade').classList.add('hidden');document.getElementById('lv').textContent='LV. 1';document.getElementById('kills').querySelector('b').textContent='0'}
 document.getElementById('play').onclick=start;document.getElementById('again').onclick=start;
 setInterval(()=>{if(started&&!paused&&!over)document.getElementById('kills').querySelector('b').textContent=kills,document.getElementById('lv').textContent='LV. '+level,document.getElementById('xpbar').style.width=(xp/nextXP*100)+'%'},100);
